from flask import Flask, request

app = Flask(__name__)

@app.route('/chat')
def chat():
    message1 = request.args.get('message1')
    message2 = request.args.get('message2')

    html = f"<h1>Chat</h1><p>{message1}</p><p>{message2}</p>"
    return html

if __name__ == '__main__':
    app.run()

