from flask import Flask, request

app = Flask(__name__)

@app.route("/confirm", methods=['POST'])
def confirm():
    document = request.form['document']
    confirmation = "Document received and confirmed"

    html = f"<h1>{confirmation}</h1><p>{document}</p>"
    return html

if __name__ == "__main__":
   app.run()

